import {graphY} from './b39-model.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(action,label)=>`<button type="button" data-x="s39-${action}">${esc(label)}</button>`;
const input=(key,label,v)=>`<label class="s39-field">${esc(label)}<input data-xfield="${key}" value="${esc(v)}" maxlength="160" autocomplete="off"></label>`;
const select=(key,label,v,opts)=>`<label class="s39-field">${esc(label)}<select data-xfield="${key}"><option value="">选择</option>${opts.map(([id,name])=>`<option value="${esc(id)}" ${id===v?'selected':''}>${esc(name)}</option>`).join('')}</select></label>`;
function graph(t,m){const X=x=>52+(x-t.xMin)/(t.xMax-t.xMin)*440,Y=y=>245-(y-t.yMin)/(t.yMax-t.yMin)*190,x=Number(m.cursor),pts=[];for(let i=0;i<=160;i++){const xx=t.xMin+(t.xMax-t.xMin)*i/160;pts.push(`${i?'L':'M'}${X(xx).toFixed(1)} ${Y(graphY(t,xx)).toFixed(1)}`);}const xt=Array.from({length:t.xMax-t.xMin+1},(_,i)=>i+t.xMin),yt=Array.from({length:t.yMax-t.yMin+1},(_,i)=>i+t.yMin),axisY=Y(0),axisX=X(0),lines=xt.map(n=>`<path d="M${X(n)} 55V245"/><text x="${X(n)}" y="264" text-anchor="middle">${n}</text>`).join('')+yt.map(n=>`<path d="M52 ${Y(n)}H492"/><text x="42" y="${Y(n)+4}" text-anchor="end">${n}</text>`).join(''),extra=t.mode==='intersection'?`<path class="s39-second" d="M${X(t.xMin)} ${Y(t.xMin)} L${X(t.xMax)} ${Y(t.xMax)}"/><text x="360" y="75">另一条线：y＝x</text>`:'',marks=m.board.marks.map(q=>`<circle cx="${X(q)}" cy="${Y(graphY(t,q))}" r="5" fill="#c57c59"/>`).join('');return `<svg class="s39-graph" viewBox="0 0 550 290" role="img" aria-label="有刻度的${t.graph==='journey'?'路程时间图':'曲线图'}"><g class="s39-grid">${lines}</g><path class="s39-axis" d="M52 ${axisY}H492 M${axisX} 55V245"/><path class="s39-curve" d="${pts.join(' ')}"/>${extra}<path class="s39-guide" d="M${X(x)} 55V245"/><circle cx="${X(x)}" cy="${Y(graphY(t,x))}" r="5" fill="#4e8071"/>${marks}<text x="488" y="283" text-anchor="end">${esc(t.xLabel||'x')}</text><text x="52" y="37">${esc(t.yLabel||'y')}</text></svg><p>绿色线的位置：${esc(m.cursor)}；橙色点是已留下的位置。</p>`;}
function chart(t,m){const trail=[t.start,...m.board.moves.filter(v=>v.correct).map(v=>v.to)];return `<div class="s39-chart" role="img" aria-label="1到100，每行10个数的百数表">${Array.from({length:100},(_,i)=>`<span class="${m.board.current===i+1?'current':trail.includes(i+1)?'visited':''}">${i+1}</span>`).join('')}</div><p>现在在 ${m.board.current}，已经走了 ${m.board.moves.filter(v=>v.correct).length} 步。</p>`;}
function calc(t,m){const b=m.board,last=b.runs.at(-1),fresh=last&&last.entry===m.entry;return `${b.estimate!==null?`<div class="s39-estimate">你先估计：<strong>${esc(b.estimate)}</strong>${Number(m.estimate)!==b.estimate?'（数字改了，可重新留下）':''}</div>`:'<p>先留下一个大概值，后面再打开计算器。</p>'}${t.candidate?`<p>有人得到 <strong>${esc(t.candidate)}</strong>。它和你估计的量级接近吗？</p>`:''}${last?`<div class="s39-result"><span>${esc(last.entry)}</span><strong>${fresh?(last.value===null?'检查输入':esc(last.value)):'输入改了，请重新计算'}</strong></div>`:''}`;}
function choose(t,m){const last=m.board.runs.at(-1),fresh=last&&last.entry===m.entry;return `<div class="s39-choice-art"><strong>${esc(t.display)}</strong><span>可以选自己觉得顺手的方法。</span></div>${last?`<div class="s39-result"><span>${esc(last.entry)}</span><strong>${fresh?(last.value===null?'检查输入':esc(last.value)):'输入改了，请重新计算'}</strong></div>`:''}`;}
export function visual(t,m){return `<div class="s39-world">${t.type==='x-s39-graph'?graph(t,m):t.type==='x-s39-chart'?chart(t,m):t.type==='x-s39-calc'?calc(t,m):choose(t,m)}</div>`;}
export function controls(t,m){let s='<div class="s39-controls">';if(t.type==='x-s39-graph'){s+=`<label class="s39-range">移动到哪个横向位置<input data-xfield="cursor" type="range" min="${t.xMin}" max="${t.xMax}" step="0.1" value="${esc(m.cursor)}"></label>`+btn('mark','留下这个位置');if(t.mode==='roots'||t.mode==='intersection')s+=btn('undo','撤回一个位置');else s+=input('answer',t.answerLabel||'这里大约是多少',m.answer);if(t.judgment)s+=select('judgment','这段水平线表示什么',m.judgment,[['stopped','距离没变，停留了一段时间'],['moving','距离一直增加']]);}
 else if(t.type==='x-s39-chart'){if(m.board.moves.filter(v=>v.correct).length<t.count)s+=input('guess','猜下一站',m.guess)+btn('hop','向前走'+t.step);else if(t.judgment)s+=select('judgment','这些落下的数',m.judgment,[['even','都是偶数'],['odd','都是奇数']]);}
 else if(t.type==='x-s39-calc'){s+=input('estimate','先估个大概',m.estimate)+btn('estimate','留下估计');if(m.board.estimate!==null){if(t.candidate)s+=select('judgment','那个人的结果',m.judgment,[['suspect','量级差很多，要重新检查'],['fine','只要显示出来就一定对']]);s+=input('entry','输入算式（可用 +、×、括号）',m.entry)+btn('run','计算')+input('answer','最后结果',m.answer);}}
 else{s+=select('method','你想怎么试',m.method,[['mental','用数的关系算'],['written','写下来逐步算'],['calculator','用计算器']]);if(m.method==='calculator')s+=input('entry','输入算式',m.entry)+btn('run','计算');s+=input('answer','你算得多少',m.answer);}
 if(m.issue)s+=`<p class="s39-issue" role="status">${esc(m.issue)}</p>`;return s+`<details><summary>留下自己的想法（可选）</summary><label class="s39-field">我的解释或新问题<textarea data-xfield="prose" maxlength="2000">${esc(m.prose)}</textarea></label><small>原话会保存，暂不自动判断。</small></details></div>`;}
export const render=(t,m)=>`<div id="extra-visual">${visual(t,m)}</div><div id="extra-controls">${controls(t,m)}</div>`;
